  "شيك مبدئي": "Pre-bill",
  "الإيصال بيتبني من البيانات المحفوظة بس — مفيش أي حساب جديد. النسخة بيتكتب عليها \"نسخة\" ومش بتعمل إيصال جديد.": "The receipt is built from saved data only — nothing is recalculated. A copy is marked \"Copy\" and does not create a new receipt.",
