  "الخدمة مش على الإيصال الإلكتروني لحد قرار المحاسب (OD-EG-4)": "Service is not on the e-receipt until the accountant decides (OD-EG-4)",
  "شكرًا لزيارتكم": "Thank you for your visit",
  "ترتيب السطور: إجمالي الأصناف ← الخصم ← الخدمة ← ضريبة القيمة المضافة ← الإجمالي. الخدمة سطر لوحدها بين الإجمالي والضريبة.": "Line order: items total → discount → service → VAT → total. Service is its own line between the total and the tax.",
  "الشيك المبدئي \"ليست فاتورة ضريبية\": مفيهوش QR، وطباعته مش بتغير الشيك ومش محتاجة موافقة.": "The pre-bill is \"Not a tax invoice\": it has no QR, and printing it does not change the check or need approval.",
