  "المرتجع فلوس بتطلع بموافقة مدير تاني. مش إرجاع فعلي للصنف ولا إشعار دائن ضريبي (قرار مفتوح H2).": "A refund is money paid out with approval from another manager. It is not a physical return of the item or a tax credit note (open decision H2).",
