  "الموافقة REFUND_APPROVE دايمًا، ومن مدير غير اللي طلب (SelfApprovalPolicy). الصرف الكاش بيطلع من درج مفتوح على الجهاز ده ويتحسب في يوم الصرف.": "REFUND_APPROVE approval is always required, from a manager other than the requester (SelfApprovalPolicy). Cash payouts come from an open drawer on this terminal and count on the payout day.",
