  "اتجاه مقترح: Reservation.* موقوفة لقرار (PD_HELD)، والعربون عملية مقترحة. العربون التزام مش مبيعات لحد ما يتخصم من شيك.": "Proposed direction: Reservation.* is on hold pending a decision (PD_HELD), and the deposit is a proposed operation. A deposit is a liability, not sales, until it is applied to a check.",
