  "اتسجل عدم حضور — العربون اتصادر": "No-show recorded — deposit forfeited",
  "العربون بيدخل الدرج لو كاش، بس محاسبيًا التزام. بيتحول مبيعات لما يتخصم من شيك (من شاشة التحصيل)، أو يتصادر لو العميل ما جاش (سؤال للمحاسب: إيراد ولا لأ؟).": "A cash deposit goes into the drawer, but in accounting it is a liability. It becomes sales when applied to a check (from the Payment screen), or is forfeited if the customer does not show up (question for the accountant: revenue or not?).",
