  "الدرج اتفتح (اتسجل)": "Drawer opened (recorded)",
  "افتح الدرج": "Open drawer",
  "مفيش فلوس بتتحرك، بس الفتحة بتتسجل في تقرير الاستثناءات. الموافقة حسب DRAWER_NO_SALE (الافتراضي: مش محتاجة).": "No money moves, but the open is recorded in the exceptions report. Approval per DRAWER_NO_SALE (default: not required).",
