  "تقرير Z": "Z report",
  "الوردية اتقفلت": "Shift closed",
  "قفل الوردية": "Close shift",
  "اقفل": "Close",
  "إقفال أعمى: اعد الدرج واكتب المبلغ من غير ما تشوف المتوقع (BlindClosePolicy). الفرق بيطلع من السيرفر بعد القفل.": "Blind close: count the drawer and enter the amount without seeing the expected figure (BlindClosePolicy). The server computes the difference after closing.",
  "الإقفال الأعمى مقفول: المتوقع": "Blind close is off: expected",
  "الكاش المعدود في الدرج": "Cash counted in the drawer",
  "ملاحظة (لو في فرق)": "Note (if there is a difference)",
  "الفرق فوق حد SESSION_VARIANCE بيطلب موافقة مدير. شيكات الصالة المأكدة والمش مدفوعة مش بتمنع القفل — بتظهر في Z كشيكات مفتوحة. طلبات التيك أواي المفتوحة على الوردية دي بتمنع (SESSION_HAS_OPEN_ORDERS).": "A difference above the SESSION_VARIANCE limit needs manager approval. Confirmed but unpaid dine-in checks do not block closing — they appear in the Z report as open checks. Open takeaway orders on this shift do block it (SESSION_HAS_OPEN_ORDERS).",
  "توزيع البقشيش": "Tip distribution",
  "البقشيش اتوزع": "Tips distributed",
  "وزّع": "Distribute",
  "البقشيش فلوس لوحدها مش مبيعات. TipPolicy لازم تكون ON (من لوحة الإعدادات) عشان يظهر في الدفع. التوزيع حسب TipDistributionPolicy (لكل ويتر أو صندوق مشترك).": "Tips are money on their own, not sales. TipPolicy must be ON (in the settings panel) for tips to appear at payment. Distribution follows TipDistributionPolicy (per waiter or shared pool).",
  "الموافقات والسجل": "Approvals and audit",
  "كل موافقة مدير بتتستخدم مرة واحدة، ومربوطة بالعملية والسياق والطالب والفرع والجهاز، وليها وقت انتهاء. السجل بيقول مين عمل إيه، وبأي أمر، وبأي موافقة.": "Every manager approval is single-use, bound to the operation, context, requester, branch and terminal, and has an expiry. The audit log says who did what, with which command, and under which approval.",
  "الموافقات": "Approvals",
  "الموافقات (Approval grants)": "Approvals (Approval grants)",
  "كل العمليات": "All operations",
  "الطالب": "Requester",
  "الموافق": "Approver",
  "على إيه": "For what",
  "اتمنحت": "Granted",
