  "اتستخدمت": "Used",
  "مستنية الاستخدام": "Awaiting use",
  "انتهت من غير استخدام": "Expired unused",
  "السياق": "Context",
  "مفيش موافقات لسه": "No approvals yet",
  "سجل العمليات (Audit)": "Audit log",
  "الحساس بس": "Sensitive only",
  "المستخدم": "User",
  "الملخص": "Summary",
  "حساس": "Sensitive",
  "الموافقة": "Approval",
  "مفيش عمليات متسجلة": "No operations recorded",
  "بيظهر آخر {n} عملية.": "Showing the last {n} operations.",
  "كل شيك بيخلص بيطلع له إيصال إلكتروني من البيانات المتجمدة وقت الإقفال. الإرسال للمنصة بيحصل بعد البيع — عمره ما بيوقف بيع.": "Every completed check gets an e-receipt built from the data frozen at close. Submission to the platform happens after the sale — it never blocks a sale.",
  "افحص السلسلة": "Verify chain",
  "تحديث": "Refresh",
  "وضع الإيصال الإلكتروني": "E-receipt mode",
  "مقفول — مفيش إيصالات بتتعمل": "Off — no e-receipts are created",
  "تجريبي — بيتبعت لبيئة التجربة": "Sandbox — sent to the test environment",
  "إنتاج — إيصالات حقيقية": "Production — real e-receipts",
  "بيتغير من لوحة السياسات، وممكن يختلف لكل فرع. الإنتاج بس بعد ملف ضريبي وأجهزة نشطة.": "Changed from the policy panel, and can differ per branch. Production only after a tax profile and active devices.",
  "مش متاح للمستخدم ده (settings:read)": "Not available for this user (settings:read)",
  "المهلة 24 ساعة": "24-hour deadline",
  "عدّى 12 ساعة": "Over 12 hours",
  "عدّى 20 ساعة": "Over 20 hours",
  "أي إيصال ما اتقبلش بيطلع تنبيه عند 12 ساعة (تحذير) و20 ساعة (خطر) قبل آخر ميعاد 24 ساعة. جرّب تقدّم الساعة من أدوات العرض.": "Any e-receipt not accepted raises an alert at 12 hours (warning) and 20 hours (danger) before the 24-hour deadline. Try advancing the clock from the demo tools.",
  "الخدمة والإيصال": "Service and e-receipt",
  "الخدمة بتفضل برة الإيصال الإلكتروني لحد ما المحاسب يحدد هي T9 ولا T17 (OD-EG-4). عشان كده المشكلة SERVICE_CHARGE_UNMAPPED معلومة بس — مش بتوقف بناء الإيصال.": "Service stays off the e-receipt until the accountant decides whether it is T9 or T17 (OD-EG-4). So the SERVICE_CHARGE_UNMAPPED issue is informational only — it does not block building the e-receipt.",
  "فيه {n} إيصال قرب على آخر ميعاد (24 ساعة) — صلّح البيانات أو اعمل إعادة إصدار.": "{n} e-receipts are near the deadline (24 hours) — fix the data or reissue.",
  "فحص سلسلة الإيصالات": "E-receipt chain check",
