  "الإيصال اتبنى واتربط بالسلسلة — هيتبعت للمنصة أوتوماتيك": "E-receipt built and linked to the chain — it will be sent to the platform automatically",
  "اتعمل إيصال مصحح بيشاور على الإيصال المرفوض (referenceOldUUID)": "A corrected e-receipt was created that references the rejected one (referenceOldUUID)",
  "إعادة بناء الإيصال": "Rebuild e-receipt",
  "الإيصال هيتبني تاني من نفس البيانات المتجمدة بعد ما صلّحت البيانات الناقصة (مثلًا أكواد الأصناف من شاشة التسجيل الضريبي). لو لسه فيه حاجة ناقصة هيفضل \"مستني بيانات\".": "The e-receipt will be rebuilt from the same frozen data after you fix the missing data (e.g. item codes from the Tax registration screen). If something is still missing, it stays \"Awaiting data\".",
  "الإيصال المرفوض هيبقى \"اتستبدل\"، وهيتعمل إيصال جديد بيشاور عليه (referenceOldUUID). الشيك نفسه مش بيتغير.": "The rejected e-receipt becomes \"Replaced\", and a new e-receipt referencing it is created (referenceOldUUID). The check itself does not change.",
  "السبب (مطلوب)": "Reason (required)",
  "التسجيل الضريبي": "Tax registration",
  "تجهيز الإيصال الإلكتروني (منظومة الإيصال الإلكتروني — مصلحة الضرائب): ملف الفرع، جهاز ضريبي لكل كاشير، وكود لكل صنف. أي بيانات ناقصة بتخلّي الإيصال \"مستني بيانات\" — والبيع بيكمل عادي.": "E-receipt setup (ETA e-receipt system — Egyptian Tax Authority): branch profile, a tax device per cashier, and a code per item. Any missing data leaves the e-receipt \"Awaiting data\" — and sales continue as usual.",
  "طابور الإيصالات": "E-receipt queue",
  "القراءة هنا من FiscalSetup.Get": "This read comes from FiscalSetup.Get",
  "— العقود فيها أوامر كتابة بس ومفيش قراءة للملف والأجهزة والأكواد، فالقراءة دي مقترحة.": "— the contracts only have write commands and no read for the profile, devices and codes, so this read is proposed.",
