  "لازم يبدأ بـ secret:// — ده اسم السر، مش السر نفسه": "Must start with secret:// — this is the secret's name, not the secret itself",
  "بيانات دخول المنظومة (client id / secret) والختم الإلكتروني بيتحفظوا في خزنة الأسرار بس. هنا بنكتب اسمها بس (OD-EG-2).": "System credentials (client id / secret) and the e-seal are stored only in the secrets vault. Here we only write their name (OD-EG-2).",
  "سجّل الجهاز": "Register device",
  "الجهاز اتوقف": "Device deactivated",
  "الجهاز اتنشط": "Device activated",
  "إيقاف جهاز ضريبي": "Deactivate tax device",
  "تنشيط جهاز ضريبي": "Activate tax device",
  "طول ما الجهاز موقوف، إيصالات الكاشير ده هتبقى \"مستني بيانات\" لحد ما يرجع نشط أو يتسجل جهاز تاني. البيع مش بيقف.": "While the device is inactive, this cashier's e-receipts will be \"Awaiting data\" until it is active again or another device is registered. Sales do not stop.",
  "اتحفظ {n} كود — روح طابور الإيصالات واعمل \"إعادة بناء\" للإيصالات اللي مستنية": "{n} codes saved — go to the e-receipt queue and \"Rebuild\" the waiting e-receipts",
  "أكواد الأصناف (EGS / GS1)": "Item codes (EGS / GS1)",
  "{n} صنف من غير كود": "{n} items without a code",
  "كل الأصناف ليها كود": "All items have a code",
  "الناقص بس": "Missing only",
  "كل سطر على الإيصال لازم يبقى له كود صنف مسجل ونوع وحدة. أي صنف من غير كود بيخلّي إيصاله \"مستني بيانات\" (ITEM_CODE_MISSING) لحد ما تضيف الكود وتعمل إعادة بناء. الأكواد بتتخزن في محوّل الإيصال المصري بس، مش في المنيو.": "Every line on the e-receipt needs a registered item code and a unit type. Any item without a code leaves its e-receipt \"Awaiting data\" (ITEM_CODE_MISSING) until you add the code and rebuild. Codes are stored only in the Egyptian e-receipt adapter, not in the menu.",
