  "ارفع شيت المنيو (Excel أو CSV) — بيتقري في المتصفح، تجرّبه الأول وتشوف الغلطات صف صف، وبعدين تطبقه كله أو لا شيء": "Upload the menu sheet (Excel or CSV) — it is read in the browser; dry-run it first and see the errors row by row, then apply it all or nothing",
