  "أول خطوات التجهيز (J-A1 من 2 لـ 4): بيانات النشاط، الفروع بالتقويم بتاعها، والأجهزة. كل جهاز جديد بيظهر فوق كشريحة جهاز تقدر تشتغل عليه.": "First setup steps (J-A1, 2 to 4): business details, branches with their calendar, and terminals. Each new terminal appears at the top as a terminal tab you can work on.",
  "بيانات النشاط": "Business details",
  "الاسم (إنجليزي)": "Name (English)",
  "لسه متكتبش": "Not entered yet",
