  "كود خصم أو عرض بمواعيد (هابي أور) — خصم على الشيك كله قبل الضريبة": "A discount code or a timed promotion (happy hour) — a discount on the whole check before tax",
  "عرض جديد": "New promotion",
  "أوتوماتيك": "Automatic",
  "مقفول": "Off",
  "مفيش تجميع: الشيك عليه خصم واحد بس — يا عرض يا خصم مدير.": "No stacking: a check has only one discount — either a promotion or a manager discount.",
  "التجميع مسموح: عرض + خصم مدير على نفس الشيك.": "Stacking allowed: promotion + manager discount on the same check.",
  "العروض الأوتوماتيك بتتطبق لوحدها.": "Automatic promotions apply on their own.",
  "العرض الأوتوماتيك (هابي أور) بيظهر للكاشير كاقتراح وهو اللي بيطبقه — مش بيتطبق لوحده.": "The automatic promotion (happy hour) is shown to the cashier as a suggestion, and the cashier applies it — it does not apply on its own.",
  "العروض متوقفة على قرار صاحب المنتج PD-V4-11 (اختيار B: أكواد وعروض بمواعيد).": "Promotions depend on product owner decision PD-V4-11 (option B: codes and timed promotions).",
