  "مفعّل": "Enabled",
  "كود": "Code",
  "كل الفروع": "All branches",
  "بيعدي نص الليل": "Crosses midnight",
  "طول الوقت": "All the time",
  "\"شغال دلوقتي\" من السيرفر حسب ساعة النظام وتوقيت الفرع — حرّك الساعة من المحاكاة عشان تجرب الهابي أور.": "\"Active now\" comes from the server based on system time and the branch time zone — move the clock in Simulation to try happy hour.",
