  "حد أدنى للشيك (اختياري)": "Minimum check (optional)",
  "على المجموع قبل الخصم — السيرفر بيحسبه": "On the subtotal before discount — computed by the server",
  "القنوات": "Channels",
  "من غير اختيار = كل الفروع": "None selected = all branches",
  "مواعيد أسبوعية (هابي أور)": "Weekly schedule (happy hour)",
  "بتوقيت الفرع. لو النهاية قبل البداية العرض بيعدي نص الليل.": "In branch time. If the end is before the start, the promotion crosses midnight.",
  "العرض شغال طول الوقت جوه فترة الصلاحية": "The promotion is active all the time within its validity period",
  "صالح من (اختياري)": "Valid from (optional)",
  "صالح لحد (اختياري)": "Valid until (optional)",
  "مش في CORE: عروض على أصناف معينة (اشتري واحد وخد التاني)، حد استخدام لكل ضيف، ونقاط الولاء.": "Not in CORE: promotions on specific items (buy one get one), per-guest usage limits, and loyalty points.",
  "مش متاح": "Not available",
  "مفيش بيانات في الفترة دي": "No data for this period",
  "ملف المحاسب اتنزل": "Accountant file downloaded",
  "تقارير اليوم التجاري (من 04:00 لـ 04:00 بتوقيت القاهرة) — قراءة بس، عمرها ما بتغير حاجة. التقارير اللي بتظهر هي اللي صلاحيتك بتسمح بيها.": "Business-day reports (04:00 to 04:00 Cairo time) — read-only, they never change anything. The reports shown are the ones your permissions allow.",
  "ملف المحاسب (CSV)": "Accountant file (CSV)",
  "مفيش تقارير مسموحة للمستخدم ده": "No reports are allowed for this user",
  "فترة": "Period",
  "من يوم تجاري": "From business day",
  "لحد يوم تجاري": "To business day",
  "أقصى فترة 93 يوم": "Maximum period 93 days",
  "الفرع: فرع الجهاز ده": "Branch: this terminal's branch",
  "مبدئي — اليوم لسه ما خلصش أو فيه وردية مفتوحة": "Provisional — the day is not over yet or a shift is open",
  "نهائي للفترة": "Final for the period",
  "الأرقام ممكن تتغير: فيه وردية مفتوحة أو اليوم التجاري لسه ما انتهاش بتوقيت الفرع. تقرير Z بتاع الوردية هو المرجع.": "Figures may change: a shift is open or the business day has not ended in branch time. The shift's Z report is the reference.",
  "الخدمة مقياس لوحده ومش جوه صافي المبيعات. وسائل الدفع عمرها ما بتتسمى مبيعات. المرتجعات بتتحسب يوم صرفها. أي مقياس مش متاح بيظهر \"مش متاح\" مش صفر.": "Service is a separate measure and not part of net sales. Payment methods are never called sales. Refunds count on their payout day. Any unavailable measure shows \"Not available\", not zero.",
  "الإعدادات والأسباب": "Settings and reasons",
  "شاشة الإعدادات الحقيقية: كل تغيير صف جديد في السجل (مفيش مسح ولا تعديل لصف قديم)، وبيحتاج موافقة مدير تاني حسب قاعدة SENSITIVE_POLICY_CHANGE. لوحة الإعدادات اللي فوق هي نسخة العرض السريعة.": "The real settings screen: every change is a new row in the history (no deleting or editing an old row), and needs approval from another manager per the SENSITIVE_POLICY_CHANGE rule. The settings panel above is the quick demo version.",
  "السياسات": "Policies",
  "أسباب الإلغاء والخصم": "Void and discount reasons",
  "النطاق: النشاط كله (TENANT)": "Scope: whole business (TENANT)",
  "النطاق: فرع {c} (BRANCH)": "Scope: branch {c} (BRANCH)",
  "الترتيب: الجهاز ← الفرع ← النشاط ← الافتراضي الآمن. التغيير بيطبق على العمليات الجديدة بس، والشيكات اللي اتسجلت محتفظة بقيمتها. الموافقة لازم تيجي من مدير غير اللي طالب التغيير (مثلاً demo-manager-2).": "Order: terminal → branch → business → safe default. Changes apply to new operations only, and recorded checks keep their value. Approval must come from a manager other than the one requesting the change (e.g. demo-manager-2).",
  "القيمة الجديدة (لسه متحفظتش)": "New value (not saved yet)",
  "القيمة الفعلية": "Effective value",
  "من النطاق ده · نسخة {v}": "From this scope · version {v}",
  "موروثة من نطاق أعلى أو الافتراضي": "Inherited from a higher scope or the default",
  "آخر تغيير": "Last change",
  "النطاقات المسموحة": "Allowed scopes",
  "النطاق ده مش مسموح للسياسة دي (SETTINGS_POLICY_SCOPE_NOT_ALLOWED) — المسموح: {s}": "This scope is not allowed for this policy (SETTINGS_POLICY_SCOPE_NOT_ALLOWED) — allowed: {s}",
  "بتتعدل من لوحة الإعدادات (Policy Panel) — هنا عرض بس.": "Edited from the settings panel (Policy Panel) — view only here.",
  "حفظ…": "Saving…",
  "القاعدة": "Rule",
  "تعديل قواعد الموافقة من لوحة الإعدادات (Policy Panel). تخفيض قاعدة SENSITIVE_POLICY_CHANGE نفسه بيحتاج موافقة تحت القاعدة القديمة.": "Edit approval rules from the settings panel (Policy Panel). Lowering the SENSITIVE_POLICY_CHANGE rule itself needs approval under the old rule.",
  "مسموح يوافق على طلبه في:": "May approve their own request in:",
