  "مفيش صف في النطاق ده (أول قيمة)": "No row in this scope (first value)",
  "ملاحظة التغيير (بتتسجل في السجل)": "Change note (recorded in the history)",
  "مثلاً: صاحب المطعم وافق على ...": "e.g. the owner agreed to ...",
  "لو القاعدة بتطلب موافقة هتظهر شاشة موافقة المدير. نفس الشخص مينفعش يوافق على طلبه (SELF_APPROVAL_DENIED) — اختار مدير تاني زي demo-manager-2. الموافقة مربوطة بالقيمة القديمة والجديدة بالظبط.": "If the rule requires approval, the manager approval screen will appear. The same person cannot approve their own request (SELF_APPROVAL_DENIED) — choose another manager such as demo-manager-2. The approval is bound to the exact old and new values.",
  "مفيش تغييرات متسجلة": "No changes recorded",
  "اتوقف السبب {c}": "Reason {c} disabled",
  "اتفعّل السبب {c}": "Reason {c} enabled",
  "لكل نوع: MANAGED = الموظف يختار من القايمة دي بس (والملاحظة إجبارية لو السبب محتاجها)، FREE_TEXT = نص حر. التحويل لـ MANAGED بيتعمل من تبويب السياسات (ReasonCodePolicy) وبيترفض لو النوع مفيهوش سبب شغال، وآخر سبب شغال في نوع MANAGED مينفعش يتوقف. الكود والنوع ثابتين بعد الإنشاء.": "Per type: MANAGED = staff choose from this list only (and the note is required if the reason needs it), FREE_TEXT = free text. Switching to MANAGED is done from the Policies tab (ReasonCodePolicy) and is rejected if the type has no active reason, and the last active reason of a MANAGED type cannot be disabled. Code and type are fixed after creation.",
  "سبب جديد": "New reason",
  "مش في ReasonCodePolicy — الافتراضي نص حر": "Not in ReasonCodePolicy — default is free text",
  "افتراضي": "default",
  "النوع ده MANAGED ومفيهوش سبب شغال!": "This type is MANAGED and has no active reason!",
  "عربي": "Arabic",
  "ترتيب": "Order",
  "إجبارية": "Required",
  "تفعيل": "Enable",
