  "اتحفظ السبب": "Reason saved",
  "اتعمل السبب {c}": "Reason {c} created",
  "تعديل السبب {c}": "Edit reason {c}",
  "حروف إنجليزي كبيرة وأرقام و _ (لحد 32). تكراره في نفس النوع بيرجع REASON_CODE_TAKEN": "Uppercase English letters, digits and _ (up to 32). A duplicate within the same type returns REASON_CODE_TAKEN",
  "شكل الكود غلط": "Invalid code format",
  "الاسم بالعربي": "Arabic name",
  "اختيارية": "Optional",
  "تغيير الاسم مش بيعدّل اللي اتسجل قبل كده: كل عملية محتفظة بنسخة السبب وقت ما اتعملت. expectedVersion = {v}": "Renaming does not change what was recorded before: each operation keeps the version of the reason at the time it happened. expectedVersion = {v}",
  "كل صنف بيتبعت للمطبخ بيروح لمحطة حسب أول قاعدة تنطبق عليه. الترابيزات بتظهر في شاشة الصالة على طول.": "Every item sent to the kitchen goes to a station per the first rule that matches it. Tables appear on the Floor screen right away.",
  "الجهاز ده من غير فرع: المحطات والترابيزات تبع فرع. سجّل دخول على جهاز الفرع أو اختار الفرع من شاشة الدخول (CONTEXT_REQUIRED).": "This terminal has no branch: stations and tables belong to a branch. Sign in on a branch terminal or choose the branch on the sign-in screen (CONTEXT_REQUIRED).",
  "المحطات والتوجيه": "Stations and routing",
  "الترابيزات": "Tables",
  "اتوقفت المحطة": "Station disabled",
  "اتفعلت المحطة": "Station enabled",
  "محطات المطبخ": "Kitchen stations",
  "محطة": "Station",
  "مفيش محطات لسه": "No stations yet",
  "قواعد التوجيه": "Routing rules",
  "قاعدة": "Rule",
  "القواعد بتتقري بالترتيب من الأولوية الأصغر للأكبر، وأول قاعدة تنطبق على الصنف هي اللي بتحدد المحطة. مفيش محطة افتراضية مخفية: لازم قاعدة عامة صريحة (\"أي حاجة تانية\") في الآخر.": "Rules are read in order from the lowest priority to the highest, and the first rule that matches the item decides the station. There is no hidden default station: an explicit catch-all rule (\"anything else\") is required at the end.",
  "مفيش قاعدة عامة شغالة: أي صنف مش متطابق مع قاعدة مش هيروح لأي محطة.": "No active catch-all rule: any item not matching a rule will not go to any station.",
  "في {n} قاعدة بعد القاعدة العامة — عمرها ما هتتطبق.": "{n} rules come after the catch-all rule — they will never apply.",
  "الأولوية": "Priority",
