  "شاشة المطبخ ومتابعة الجولة على الشيك بيقولوا كل صنف راح فين فعلاً. النموذج مش بيحسب التوجيه في المتصفح.": "The kitchen display and the round tracking on the check show where each item actually went. The prototype does not compute routing in the browser.",
