  "الوجهة": "Destination",
  "\"من غير تذكرة\" (للأصناف اللي مش محتاجة مطبخ زي المية) اقتراح مش في العقد.": "\"No ticket\" (for items that need no kitchen, like water) is a proposal, not in the contract.",
