  "الضرايب": "Taxes",
  "سياسات الضريبة: النسبة، شاملة ولا فوق السعر، والتقريب. النسب بيانات صاحب المطعم — مفيش نسبة قانونية مكتوبة كحقيقة.": "Tax policies: rate, inclusive or exclusive, and rounding. Rates are owner data — no legal rate is hard-coded as fact.",
  "ضريبة جديدة": "New tax",
  "مش متحدد": "Not set",
  "اعرض المؤرشف": "Show archived",
  "تغيير النسبة أو طريقة الحساب أو التقريب محتاج موافقة حسب السياسة، وبيسري على التسعيرات الجديدة بس — السطور المسجلة بتفضل بضريبتها ونسخة السياسة. الضريبة اللي عليها أصناف ما تتأرشفش (TAX_POLICY_IN_USE)، ومفيش مسح.": "Changing the rate, calculation method or rounding needs approval per the policy, and applies to new pricing only — recorded lines keep their tax and policy version. A tax used by items cannot be archived (TAX_POLICY_IN_USE), and there is no deleting.",
