  "كود منظومة الإيصال الإلكتروني — من المحاسب": "E-receipt system code — from the accountant",
  "النوع الفرعي (fiscalSubtype)": "Subtype (fiscalSubtype)",
  "النهاردة: نسبة 0 + النوع الفرعي بيفرق بين المعفي والصفر": "Today: rate 0 + the subtype distinguishes exempt from zero-rated",
  "الأسعار شاملة الضريبة: الخدمة على منيو شامل الضريبة مش متاحة في التسعير (CAPABILITY_NOT_AVAILABLE).": "Tax-inclusive prices: service on a tax-inclusive menu is not available in pricing (CAPABILITY_NOT_AVAILABLE).",
  "تغيير الاسم بس مش محتاج موافقة. أي تغيير في النسبة أو الحساب أو التقريب أو الجهة أو أكواد الإيصال الإلكتروني بيطلب موافقة SENSITIVE_POLICY_CHANGE حسب السياسة.": "Renaming alone needs no approval. Any change to the rate, calculation, rounding, jurisdiction or e-receipt codes requires SENSITIVE_POLICY_CHANGE approval per the policy.",
  "كل مستخدم ليه دور أو أكتر، وكل دور على فروع معينة. تغيير الصلاحيات وإعادة تعيين الرقم السري ممكن يحتاجوا موافقة مدير حسب الإعدادات.": "Each user has one or more roles, each role on specific branches. Changing permissions and resetting a PIN may need manager approval depending on the settings.",
  "المستخدمين": "Users",
  "الأدوار والصلاحيات": "Roles and permissions",
  "اتوقف {n} — جلساته اتلغت": "{n} deactivated — their sessions were revoked",
