  "إيقاف مستخدم بيلغي كل جلساته فورًا: أي جهاز داخل بيه هيرجع لشاشة الدخول مع أول عملية (N8).": "Deactivating a user revokes all their sessions immediately: any terminal signed in as them returns to the sign-in screen on the next operation (N8).",
