  "الأدوار ونطاق الفروع": "Roles and branch scope",
  "في التركيب الحقيقي الرقم السري والباسورد بيوصلوا للشخص نفسه (Credential.Reset)، عمرهم ما بيتكتبوا في محضر. من غير PIN المستخدم لازم يغيّر بياناته أول ما يدخل.": "In a real installation the PIN and password are delivered to the person directly (Credential.Reset), never written in minutes. Without a PIN, the user must change their credentials on first sign-in.",
  "اتحدثت صلاحيات {n}": "{n}'s permissions updated",
