  "الإيقاف بيلغي كل جلسات المستخدم: الجهاز اللي داخل بيه هيرجع لشاشة الدخول مع أول عملية (N8).": "Deactivation revokes all the user's sessions: the terminal signed in as them returns to the sign-in screen on the next operation (N8).",
  "لو مفيش حد تاني يقدر يدير الصلاحيات، السيرفر بيرفض LAST_OWNER_PROTECTED. النسخة {v} (expectedVersion).": "If no one else can manage permissions, the server rejects with LAST_OWNER_PROTECTED. Version {v} (expectedVersion).",
