  "مش مطابق لـ CredentialPolicy — السيرفر هيرفض": "Does not match CredentialPolicy — the server will reject it",
  "إعادة التعيين بتفك القفل لو الحساب مقفول من محاولات غلط، وبتخلّي المستخدم يغيّر الرقم أول ما يدخل.": "Resetting unlocks the account if it was locked by failed attempts, and makes the user change the PIN on first sign-in.",
  "الصلاحيات اللي عليها \"أضيفت للنموذج\" مش في أدوار ملف التجهيز 1.2 — النموذج زوّدها عشان الخبير يقدر يجرب كل الشاشات (PROTOTYPE_GAPS).": "Permissions marked \"Added for prototype\" are not in the setup file 1.2 roles — the prototype added them so the expert can try all screens (PROTOTYPE_GAPS).",
