  "قاعدة واحدة ثابتة: القروش بتتوزع بأكبر باقي والفرق الأخير على آخر حصة (SplitAllocationPolicy). خصم النسبة بيتنسخ لكل حصة، وخصم المبلغ بيتوزع بنفس القاعدة، والخدمة بتتحسب لكل شيك.": "One fixed rule: piasters are distributed by largest remainder and the final difference goes to the last share (SplitAllocationPolicy). A percentage discount is copied to each share, an amount discount is distributed by the same rule, and service is computed per check.",
