  "لو غلطت 5 مرات الحساب بيتقفل 15 دقيقة.": "After 5 wrong tries the account locks for 15 minutes.",
  "عملية محتاجة موافقة": "Action needs approval",
  "الموافقة بتتستخدم مرة واحدة للعملية دي بالظبط، ومن نفس الجهاز، وبتخلص بعد دقيقتين. صاحب الطلب مينفعش يوافق لنفسه.": "The approval is single-use, for this exact action, from the same device, and expires after 2 minutes. The requester can't approve their own request.",
  "سبب من القايمة": "Reason from list",
  "مفيش نت — العملية دي مينفعش تتعمل من غير نت. استنى لما النت يرجع.": "Offline — this action can't be done offline. Wait until you're back online.",
