  "النت رجع: كل العمليات اللي اتسجلت ({n}) اتبعتت": "Back online: all saved actions ({n}) were sent",
  "ساعة التجربة: قدّم الوقت عشان تشوف اليوم التجاري، الأسعار المجدولة، الهابي أور، وتنبيهات الإيصال الإلكتروني": "Demo clock: move time forward to see the business day, scheduled prices, happy hour, and e-receipt alerts",
  "متقدمة": "Advanced",
  "ساعة التجربة": "Demo clock",
  "السيستم ليه ساعة لوحده تقدر تقدّمها. اليوم التجاري بيبدأ الساعة 4 الفجر بتوقيت القاهرة: البيع الساعة 2 بالليل بيتحسب على اليوم اللي قبله.": "The system has its own clock you can move forward. The business day starts at 4 AM Cairo time: a sale at 2 AM counts toward the previous day.",
  "قبل بداية اليوم الجديد بـ 5 دقايق": "5 minutes before the new day starts",
  "بعد بداية اليوم الجديد بـ 5 دقايق": "5 minutes after the new day starts",
  "2 بالليل — لسه على اليوم اللي فات": "2 AM — still the previous day",
  "وقت الفطار": "Breakfast time",
  "فطار": "Breakfast",
