  "هنحفظ معاها الشاشة والجهاز وإعدادات المطعم وقتها، عشان الفريق يفهم السياق.": "We'll save the screen, device and restaurant settings at the time with it, so the team gets the context.",
  "ملف الملاحظات اتحفظ": "Notes file saved",
  "الملاحظات اتنسخت — الصقها في رسالة": "Notes copied — paste them into a message",
  "شغّل «ملاحظة» من الشريط اللي فوق واضغط على أي حاجة في الشاشة. لما تخلص، نزّل الملف وابعته للفريق.": "Turn on \"Note\" from the top bar and tap anything on screen. When done, download the file and send it to the team.",
  "نزّل الملاحظات": "Download notes",
