  "«أي شرط من اتنين» لسه فكرة مقترحة ومستنية موافقة.": "\"Either of two conditions\" is still proposed and awaiting approval.",
  "اضغط على الحركة عشان تسمح للمدير يوافق على طلبه هو فيها (مش منصوح بيه).": "Tap the action to let a manager approve their own request for it (not recommended).",
  "ممنوع": "Not allowed",
  "إعدادات المطعم (للتجربة)": "Restaurant settings (demo)",
  "كل اختيار هنا بيغيّر طريقة شغل المطعم. جرّب تغيّر واحد وشوف الأجهزة بتتصرف إزاي. التغيير بيطبق على اللي جاي بس — الشيكات القديمة زي ما هي.": "Every option here changes how the restaurant runs. Change one and see how devices behave. Changes apply going forward only — existing checks stay as they are.",
  "قفل": "Close",
  "دوّر على إعداد… (مثلًا: خدمة، درج، خصم)": "Search settings… (e.g. service charge, drawer, discount)",
  "للمطعم كله": "Whole restaurant",
  "لـ{b} بس": "{b} only",
  "الفرع الرئيسي": "Main branch",
  "دي نسخة سريعة للتجربة: التغيير فوري ومن غير موافقة. في المطعم الحقيقي التغيير بيتعمل من شاشة «الإعدادات» وبيحتاج موافقة مدير تاني.": "This is a quick demo version: changes are instant and need no approval. In a real restaurant, changes are made from the \"Settings\" screen and need a second manager's approval.",
  "مفيش إعداد بالاسم ده": "No setting with that name",
  "رجعت كل الإعدادات لقيم بروفايل مصر": "All settings reset to Egypt profile values",
  "رجّع كل الإعدادات لبروفايل مصر": "Reset all settings to Egypt profile",
  "اتغيّر «{p}» — هيطبق على اللي جاي بس": "\"{p}\" changed — applies going forward only",
  "جاية من المطعم كله": "Inherited from whole restaurant",
  "الإعداد ده مينفعش يتظبط لفرع لوحده — بيتظبط للمطعم كله بس.": "This setting can't be set per branch — only for the whole restaurant.",
