  "البيانات: رجّع بيانات التجربة، ابدأ بمطعم فاضي، أو احفظ نسخة": "Data: reset demo data, start with an empty restaurant, or save a backup",
  "بيانات التجربة": "Demo data",
  "كل اللي بتعمله محفوظ في المتصفح ده بس.": "Everything you do is saved in this browser only.",
  "نرجّع كل حاجة زي ما كانت أول ما فتحت التجربة؟": "Reset everything to how it was when you first opened the demo?",
  "رجعت بيانات التجربة زي الأول": "Demo data reset",
  "رجّع بيانات التجربة زي الأول": "Reset demo data",
  "نبدأ بمطعم فاضي خالص؟ كل بيانات التجربة هتتمسح (وتقدر ترجعها من هنا).": "Start with a completely empty restaurant? All demo data will be erased (you can restore it from here).",
  "مطعم فاضي: ادخل من «الإدارة» باسم كريم (مهندس التركيب)، أو امشي مع رحلة «تركيب مطعم من الصفر»": "Empty restaurant: sign in from \"Admin\" as Karim (installer), or follow the \"Set up a restaurant from scratch\" journey",
  "ابدأ بمطعم فاضي (تركيب من الصفر)": "Start with an empty restaurant (setup from scratch)",
  "احفظ نسخة من البيانات (ملف)": "Save a data backup (file)",
  "رجّع نسخة محفوظة": "Restore a saved backup",
  "النسخة رجعت": "Backup restored",
  "بنجرّب حاجات المفروض السيستم يرفضها أو يتصرف فيها صح: ضغطتين ورا بعض، جهازين في نفس اللحظة، رد بيضيع، حد بيحاول يوافق لنفسه…": "We test things the system should reject or handle correctly: double taps, two devices at once, a lost response, someone trying to approve their own request…",
  "12 تجربة جاهزة": "12 ready-made tests",
  "1000 موقف للمناقشة": "1000 scenarios to discuss",
  "خلصت كل التجارب": "All tests done",
  "كل تجربة بتتأكد إن النتيجة زي المتوقع وإن مفيش حاجة زيادة اتسجلت. بتشتغل على بيانات التجربة الحالية.": "Each test checks the result is as expected and nothing extra was recorded. Runs on the current demo data.",
