  "مثلًا: دفعت 20 جنيه مواصلات للطيار": "E.g. paid EGP 20 transport for the driver",
  "لو فيه فرق في العد لازم مدير يوافق. شيكات الصالة اللي لسه ما اتدفعتش مش بتمنع القفل وبتظهر في التقرير. طلبات التيك أواي المفتوحة على الدرج ده لازم تتحصّل أو تتنقل لدرج تاني الأول.": "A count difference needs manager approval. Unpaid floor checks don't block closing and appear in the report. Open takeaway orders on this drawer must be settled or moved to another drawer first.",
  "البقشيش فلوس لوحدها مش مبيعات. بيتوزع حسب الإعدادات: كل ويتر بتاعه، أو صندوق مشترك بيتقسم على الكل.": "Tips are separate money, not sales. They're distributed per settings: each waiter keeps their own, or a shared pool split among everyone.",
