  "اعرض أكتر": "Show more",
  "كل شيك بيتقفل بيطلع له إيصال إلكتروني لمصلحة الضرايب. الإرسال بيحصل بعد البيع — عمره ما بيوقف بيع.": "Every closed check gets an e-receipt for the Tax Authority. Sending happens after the sale — it never stops a sale.",
