  "تنبيه بعد 12 ساعة وخطر بعد 20": "Warning after 12 hours, critical after 20",
  "الخدمة بتفضل برة الإيصال الإلكتروني لحد ما المحاسب يحدد نوع الضريبة بتاعها — ودي ملاحظة بس، مش بتوقف الإيصال.": "Service charge stays off the e-receipt until the accountant sets its tax type — this is just a note, it doesn't block the receipt.",
  "فحص تسلسل الإيصالات": "Receipt sequence check",
  "كل إيصال مربوط باللي قبله على نفس الجهاز — لو فيه إيصال ناقص أو متغير السلسلة بتتكسر.": "Each receipt is chained to the previous one on the same device — a missing or altered receipt breaks the chain.",
  "الفحص الكامل على السيرفر لسه مش متاح للحساب ده — ده فحص سريع من الإيصالات اللي في الطابور.": "The full server check isn't available for this account yet — this is a quick check from receipts in the queue.",
  "جهاز ضريبي": "Tax device",
  "كل الإيصالات ماشية تمام. لو صنف ناقصه كود، الإيصال بتاعه هيظهر هنا.": "All receipts are fine. If an item is missing a code, its receipt will show here.",
  "اقفل شيك على الكاشير وإيصاله هيظهر هنا.": "Close a check on the cashier and its receipt will show here.",
  "المنظومة رفضت الإيصال — صلّح البيانات واعمل إيصال مصحح.": "The tax system rejected the receipt — fix the data and issue a corrected receipt.",
