  "المنظومة": "Tax system",
  "لسه فيه بيانات ناقصة — الإيصال فاضل مستني": "Data still missing — the receipt is still pending",
  "اتعمل إيصال مصحح بيشاور على الإيصال المرفوض": "A corrected receipt referencing the rejected one was issued",
  "الإيصال هيتبني تاني من نفس بيانات الشيك بعد ما صلّحت الناقص (مثلًا أكواد الأصناف من شاشة التسجيل الضريبي). لو لسه فيه حاجة ناقصة هيفضل مستني.": "The receipt will be rebuilt from the same check data after you've fixed what was missing (e.g. item codes from the Tax registration screen). If anything is still missing it will stay pending.",
  "الإيصال المرفوض هيتعلم «اتستبدل»، وهيتعمل إيصال جديد بيشاور عليه. الشيك نفسه مش بيتغير.": "The rejected receipt will be marked \"Replaced\", and a new receipt referencing it will be issued. The check itself doesn't change.",
  "تجهيز الإيصال الإلكتروني مع مصلحة الضرايب: بيانات الفرع، جهاز ضريبي لكل كاشير، وكود لكل صنف. أي بيانات ناقصة بتخلّي الإيصال يستنى — والبيع بيكمل عادي.": "Set up e-receipts with the Tax Authority: branch details, a tax device per cashier, and a code per item. Any missing data makes the receipt wait — sales continue normally.",
