  "كل ورقة بتطلع من السيستم بتستنى هنا لحد ما الطابعة تستلمها. البيع بيتسجل الأول — عطل الطابعة عمره ما بيوقف بيع.": "Every slip from the system waits here until the printer picks it up. The sale is recorded first — a printer failure never stops a sale.",
