  "بيع حاجة على الكاشير وهتظهر هنا.": "Sell something on the cashier and it'll show here.",
  "خمس حاجات تعرفها عن الطابعة والطابور.": "Five things to know about the printer and the queue.",
  "«إعادة» بترجّع نفس الورقة للطابور — عمرها ما بتطلع نسخة زيادة. الورقة اللي اتبعتت أو لسه مستنية مينفعش تتعاد.": "\"Retry\" puts the same slip back in the queue — it never produces an extra copy. A slip that's been sent or is still waiting can't be retried.",
  "«اطبع نسخة» بتطبع ورقة جديدة مكتوب عليها «نسخة»، مش إيصال جديد. ممكن تحتاج موافقة مدير حسب الإعدادات (أول نسخة من غير موافقة وبعدها موافقة).": "\"Print copy\" prints a new slip marked \"Copy\", not a new receipt. It may need manager approval per settings (first copy without approval, then with approval).",
  "العرض اتعدل — الشيكات اللي عليها العرض بتفضل بالنسخة القديمة": "Promotion updated — checks with the promotion keep the old version",
  "هابي أور، خصم على أصناف معينة، اشتري وخد، وأكواد خصم — بمواعيد وحدود استخدام. السيستم هو اللي بيحسب الخصم على الشيك.": "Happy hour, discounts on specific items, buy-and-get, and discount codes — with schedules and usage limits. The system calculates the discount on the check.",
  "شغالة دلوقتي": "Active now",
  "الشيك عليه خصم واحد بس: يا عرض يا خصم مدير.": "A check gets only one discount: either a promotion or a manager discount.",
  "ينفع أكتر من خصم على نفس الشيك — بس العرض اللي متعلم \"لوحده\" مش بيتجمع مع حاجة.": "Multiple discounts can apply to the same check — but a promotion marked \"exclusive\" doesn't stack with anything.",
  "العروض الأوتوماتيك بتتطبق لوحدها أول ما الشيك يستاهلها.": "Automatic promotions apply on their own as soon as the check qualifies.",
  "العروض الأوتوماتيك بتظهر للكاشير كاقتراح وهو اللي بيطبقها.": "Automatic promotions appear to the cashier as a suggestion and they apply them.",
