  "أول ما الجرد يبدأ، السيستم بيحفظ رصيد كل صنف. أي بيع أو استلام بيحصل وانتو بتعدّوا بيتحسب لوحده في الفرق — مش لازم تقفلوا المحل.": "As soon as the count starts, the system saves each item's balance. Any sales or receipts while you count are accounted for in the variance automatically — no need to close the store.",
