  "راجع الفروقات: بالأحمر عجز، بالأخضر زيادة. الاعتماد بيعمل حركة \"فرق جرد\" لكل صنف بقيمته بالتكلفة، وبيحتاج موافقة مدير لو فيه أي فرق.": "Review variances: red is shortage, green is overage. Approving creates a \"Count variance\" movement for each item at cost, and requires manager approval if there's any variance.",
