  "التحويلات": "Transfers",
  "نقل بضاعة من مخزن لمخزن: من المخزن الرئيسي للمطبخ، أو لفرع تاني. البضاعة بتطلع من المخزن أول ما تتبعت، وبتدخل لما تتستلم.": "Move goods between warehouses: from the main warehouse to the kitchen, or to another branch. Goods leave stock when sent, and enter when received.",
