  "المخازن": "Warehouses",
  "كل فرع ليه مخزن رئيسي ومطبخ (ولو حابب بار). مخزن البيع ★ هو اللي المبيعات بتسحب منه الخامات.": "Each branch has a main warehouse and a kitchen (and a bar if you like). The ★ sales warehouse is where sales deduct ingredients from.",
  "مخزن جديد": "New warehouse",
  "لسه مفيش مخازن. ضيف مخزن رئيسي ومطبخ لكل فرع — أول مخزن في الفرع بيبقى مخزن البيع.": "No warehouses yet. Add a main warehouse and a kitchen for each branch — the first warehouse in a branch becomes the sales warehouse.",
