  "اللي اتحرق أو باظ أو وقع، التسويات اليدوية، ومرتجعات الزباين — كل واحدة بقيمتها وسببها ومين وافق.": "What got burned, spoiled or dropped, manual adjustments, and customer returns — each with its value, reason and who approved.",
