  "طبق": "Dish",
  "التسوية للحالات اللي مش هالك ومش جرد: تصحيح إدخال غلط، حاجة اتلقت أو ضاعت، استهلاك العاملين. كل تسوية بموافقة مدير تاني.": "Adjustments are for cases that aren't waste or a count: fixing a data-entry error, something found or lost, staff meals. Every adjustment needs a second manager's approval.",
  "تسوية جديدة": "New adjustment",
  "مفيش تسويات": "No adjustments",
  "لما زبون يرجّع صنف: لو ينفع يرجع المخزن (كانز، مياه مقفولة) اختار \"يرجع المخزن\". الأكل اللي اتعمل بيتسجل \"يترمي\" — مفيش حركة مخزن لأنه اتسحب وقت البيع.": "When a customer returns an item: if it can go back to stock (cans, sealed water) choose \"Back to stock\". Prepared food is recorded as \"Discard\" — no stock movement since it was deducted at sale.",
