  "منيو جديد": "New menu",
  "مفيش منيو شغال — كل الأصناف بتظهر طول اليوم في كل القنوات. أول ما تشغّل منيو، الكاشير هيشوف اللي في المنيوهات الشغالة بس.": "No active menu — all items show all day on every channel. Once you activate a menu, the cashier only sees what's in active menus.",
  "مش وقته": "Not available now",
  "الصنف بيظهر على الكاشير لو موجود في منيو شغال للقناة والفرع والفترة دي. الصنف اللي برا مواعيده بيختفي ويرجع لوحده.": "An item shows on the cashier if it's in an active menu for this channel, branch and daypart. Items outside their hours disappear and return automatically.",
