  "حرّك الساعة الوهمية من فوق عشان تشوف الفطار يظهر ويختفي.": "Move the simulated clock above to see breakfast appear and disappear.",
  "علّم الأصناف والإضافات اللي خلصت — بتختفي من البيع على كل الأجهزة فورًا، وبترجع لوحدها أول اليوم التجاري الجاي": "Mark items and modifiers that are sold out — they disappear from sale on all devices immediately and come back automatically at the start of the next business day",
