  "—": "—",
  "طلبات الموافقة": "Approval requests",
  "الكاشير أو الويتر لما يحتاج موافقة يقدر يبعتها هنا بدل ما تروح له. موافقتك بتتستخدم مرة واحدة للعملية دي بالظبط.": "When the cashier or waiter needs approval, they can send it here instead of you going over. Your approval is used once, for that exact operation.",
  "اتردّ عليها": "Responded",
  "مفيش طلبات مستنية دلوقتي": "No pending requests right now",
  "جرّب: على الكاشير اعمل خصم كبير، وفي شاشة الموافقة اضغط \"ابعت طلب للمدير\".": "Try it: on the cashier, apply a large discount, and on the approval screen tap \"Send request to manager\".",
  "وافقت — العملية هتكمل على {d}": "Approved — the operation will complete on {d}",
