  "لو وافقت، {n} مش هيحتاج يعمل حاجة — العملية هتكمل لوحدها على جهازه.": "If you approve, {n} won't need to do anything — the operation will complete on its own on their device.",
  "قفل اليوم": "Day close",
  "اليوم التجاري بيبدأ الساعة 4 الفجر بتوقيت القاهرة وبيخلص 4 الفجر اللي بعده — البيع الساعة 2 بالليل تبع اليوم اللي قبله. القفل بيثبّت أرقام اليوم ويبعتها للحسابات.": "The business day starts at 4 AM Cairo time and ends at 4 AM the next day — a sale at 2 AM belongs to the previous day. Closing locks the day's figures and sends them to accounting.",
