  "تقفل يوم {d}؟ بعد القفل أرقام اليوم بتتثبت وتتبعت للحسابات ومش هتتغير.": "Close {d}? After closing, the day's figures are locked, sent to accounting, and won't change.",
  "أيوه، اقفل اليوم": "Yes, close the day",
