  "اقفل اليوم": "Close day",
  "فيه حاجات لازم تخلص الأول (اللي باللون الأحمر). اضغط \"روح\" جنب كل واحدة.": "Some items must be resolved first (in red). Tap \"Go\" next to each one.",
  "شفت التحذيرات ({n}) وعايز أقفل برضه — هتتسجل مع القفل.": "I've seen the warnings ({n}) and want to close anyway — they'll be recorded with the close.",
  "كله تمام — تقدر تقفل اليوم.": "All good — you can close the day.",
  "ملاحظة للحسابات (اختياري)": "Note for accounting (optional)",
  "مثلاً: الكهربا قطعت ساعة": "e.g. Power was out for an hour",
  "اقفل يوم {d}": "Close {d}",
  "بعد القفل الأرقام بتتثبت وتتبعت لبرنامج الحسابات. لو حصل بيع قبل 4 الفجر هيتسجل على نفس اليوم ويظهر \"بعد القفل\".": "After closing, the figures are locked and sent to the accounting software. Any sale before 4 AM is recorded on the same day and shows as \"After close\".",
  "تحذيرات اتشافت": "Warnings acknowledged",
  "{n} شيك اتقفل بعد قفل اليوم (قبل 4 الفجر) — بيظهروا في تقرير اليوم ده كـ\"بعد القفل\".": "{n} checks closed after the day close (before 4 AM) — they appear in this day's report as \"After close\".",
  "أرقام اليوم (متثبتة)": "Day figures (locked)",
  "رجعت زي إعداد النشاط": "Reverted to business setting",
  "{x} اتفتحت": "{x} enabled",
  "{x} اتقفلت — الشاشات بتاعتها اختفت": "{x} disabled — its screens are hidden",
  "إمكانيات النظام": "System features",
  "افتح أو اقفل أجزاء كاملة من السيستم حسب طريقة شغل المطعم. اللي بيتقفل بتختفي شاشاته من كل الأجهزة، ولو حد حاول يستخدمه السيستم بيقوله إنه مقفول.": "Turn entire parts of the system on or off to fit how the restaurant works. When disabled, its screens disappear from all devices, and anyone who tries to use it is told it's off.",
  "النشاط كله": "Whole business",
  "الفرع ده بس": "This branch only",
  "إعداد الفرع بيغلب إعداد النشاط. \"زي النشاط\" بيشيل استثناء الفرع.": "Branch setting overrides the business setting. \"Same as business\" removes the branch override.",
