  "فيه تعديلات ما اتحفظتش على القسم ده. تسيبها؟": "This section has unsaved changes. Leave anyway?",
  "خريطة الصالة": "Floor plan",
  "اقسم المطعم لأقسام، واسحب كل ترابيزة لمكانها الحقيقي. أول ما تحفظ، تابلت الويتر والكاشير بيشوفوا نفس الخريطة.": "Divide the restaurant into sections, and drag each table to its real position. Once saved, the waiter tablets and cashier see the same plan.",
