  "مفيش عمليات مستنية": "No pending operations",
  "الجهاز شغال على آخر بيانات عنده؛ إضافة الأصناف والإرسال للمطبخ والتحصيل الكاش بتتسجل وتتبعت لما النت يرجع.": "The device is running on its latest data; adding items, sending to the kitchen and cash payments are recorded and sent when the connection returns.",
