  "المطابقة": "Reconciliation",
  "بنقارن اللي السيستم سجله باللي حصل فعلاً: الدرج المعدود، تسوية البنك، كشف المحفظة، والإيصالات المقبولة. أي فرق بيفضل ظاهر لحد ما حد يكتب سببه — الأرقام نفسها عمرها ما بتتعدل.": "We compare what the system recorded with what actually happened: counted drawers, bank settlement, wallet statement, and accepted receipts. Any variance stays visible until someone records a reason — the figures themselves are never edited.",
