  "اكتب السبب بوضوح (5 حروف على الأقل). التفسير بيتسجل باسمك، والأرقام بتفضل زي ما هي.": "State the reason clearly (at least 5 characters). The explanation is recorded under your name, and the figures stay as they are.",
  "مثلاً: عملية كارت اتعملت مرتين على الماكينة واترجعت تاني يوم": "e.g. A card transaction was run twice on the terminal and reversed the next day",
  "مفيش رقم فعلي نقارن بيه لسه (الوردية مفتوحة أو التسوية ما وصلتش). طابق تاني بعدين.": "No actual figure to compare yet (shift still open or settlement not received). Reconcile again later.",
