  "مثلاً: أ. هاني المحاسب — أكتر من اسم بينهم فاصلة": "e.g. Mr. Hany the accountant — separate multiple names with commas",
  "قبل 4 الفجر اليوم التجاري لسه ما خلصش — التقرير هيطلع بأرقام اليوم اللي قبله لحد اللحظة دي.": "Before 4 AM the business day isn't over yet — the report will show the previous day's figures up to this moment.",
  "في البروتوتايب الإرسال بيتسجل بس (مفيش إيميل بيتبعت فعلاً).": "In the prototype, sending is only logged (no email is actually sent).",
  "المزامنة والشغل من غير نت": "Sync & offline mode",
  "لو النت قطع، الجهاز بيكمّل شغل على آخر بيانات عنده ويسجل العمليات المسموحة برقمها. أول ما النت يرجع بتتبعت بنفس الترتيب، ولو حاجة اتغيرت في النص بتظهر هنا تقرر فيها.": "If the connection drops, the device keeps working on its latest data and records allowed operations with their IDs. Once back online they're sent in the same order, and if something changed in between, it shows here for you to decide.",
  "اقطع النت عن الجهاز ده (محاكاة)": "Disconnect this device (simulate)",
  "ابعت المستني دلوقتي": "Send pending now",
  "مستني يتبعت ({n})": "Pending ({n})",
  "مفيش عمليات مستنية على الجهاز ده": "No pending operations on this device",
  "اتسجلت": "Recorded",
  "تمسح العملية دي من الجهاز؟ مش هتتبعت خالص.": "Delete this operation from the device? It will never be sent.",
  "اللي بيشتغل من غير نت": "What works offline",
  "أي حاجة تانية (خصم، إلغاء بعد الإرسال، دفع بكارت، قفل وردية) لازم نت.": "Anything else (discounts, voids after sending, card payments, closing a shift) requires a connection.",
