  "سعر": "Price",
  "سبب": "Reason",
  "اتحملت": "Downloaded",
  "من غير نت — دي آخر نسخة": "Offline — this is the latest snapshot",
  "اتغير إيه من ساعة النسخة دي": "What changed since this snapshot",
  "مفيش تغييرات — النسخة اللي على الجهاز محدثة": "No changes — the device snapshot is up to date",
  "حدّث الجهاز بالتغييرات دي": "Update device with these changes",
  "صحة النظام": "System health",
  "كل حاجة السيستم بيبعتها بعد ما البيع يتحفظ: للمطبخ والطابعة ومنظومة الضرايب والبرامج التانية. البيع نفسه عمره ما بيقف على دول — لو حاجة فشلت بتتعاد لوحدها، ولو وقفت تقدر تبعتها تاني من هنا.": "Everything the system sends after a sale is saved: to the kitchen, printer, tax system and other software. The sale itself never depends on these — if something fails it retries automatically, and if it stops you can resend it from here.",
