  "القروش بتتوزع بحيث مجموع الشيكات يساوي الأصل بالظبط. خصم النسبة بيتطبق على كل شيك، وخصم المبلغ بيتوزع، والخدمة بتتحسب لكل شيك.": "Piasters are distributed so the checks add up exactly to the original. Percentage discounts apply to each check, amount discounts are split, and service charge is calculated per check.",
